// Package rules is the rule table of the native engine: data and the checks that keep it honest,
// no scanning. rules_gen.go is generated by internal/pattern/rulegen from rules/src/*.json and
// rules/keyguard.toml and committed, so the engine parses nothing at start-up and nothing at build
// or test time needs the tools that made the data.
//
// Every rule says where it came from (Src), and provenance.go refuses any lineage or licence the
// project may not copy from. TruffleHog is not on the list and never will be.
package rules

//go:generate go run ../rulegen -repo ../../..

// Kind is how the engine runs a rule. A rule is Regex, which is Go's regexp over a window around a
// keyword hit and is exactly what its upstream regex does, unless the generator found its regex
// plain enough for a linear matcher (package lin): Shape or Assign. The regex stays in the table as
// the specification and the oracle of the differential fuzz; the matcher is held to it on 100,000
// inputs per rule. The generator sets the kind from lin.Compile, and a test says the table agrees.
type Kind uint8

const (
	Regex  Kind = iota // Go's regexp over a window
	Shape              // linear matcher: literals, classes and runs of a class, a few alternatives
	Assign             // linear matcher: a name, a separator grammar and a value, as the semi-generic rules write it
	Block              // PEM, to its end marker (not built yet)
	Pair               // an id rule and a secret rule within N lines (not built yet)
)

// String is the name the generated table writes.
func (k Kind) String() string {
	switch k {
	case Shape:
		return "Shape"
	case Assign:
		return "Assign"
	case Block:
		return "Block"
	case Pair:
		return "Pair"
	}
	return "Regex"
}

// Floor is an entropy gate. A zero Min is no gate. Strict means a value must exceed Min; otherwise
// it must reach it: betterleaks writes the first as "entropy <= Min discards" and the second as
// "entropy < Min discards", and the two differ on a value that sits exactly on the line.
type Floor struct {
	Min    float64
	Strict bool
}

// Filter is what makes an upstream rule drop a finding after its regex has matched. Each field is
// one condition, and a finding that meets any of them is dropped, except Require. The values it
// tests are the secret (the rule's group, or the whole match) and, for DropPath, the file path.
//
// Residual counts the parts of the upstream filter these fields do not carry, such as the
// provider-specific checks of the generic rules. A rule with a Residual is not judged on its
// false positives by the fidelity checks, because upstream rejects some of them by what the table
// cannot see. TokenRatio is carried as data but not evaluated: betterleaks's token-efficiency data is
// not ours, and keyguard writes its own scorer.
type Filter struct {
	Entropy    Floor
	TokenRatio float64    // dropped when the secret's token ratio reaches this; 0 is no check
	DropRegex  []string   // RE2: dropped when the secret matches any
	DropWords  []string   // dropped when the secret contains any
	DropSHA256 []string   // dropped when the sha256 of the secret is any (documentation keys, which the source may not hold)
	DropPath   []string   // RE2: dropped when the file path matches any
	Require    [][]string // RE2: dropped unless the secret matches one of every group
	Residual   int
}

// Need is a component of a composite rule: the rule with ID must also fire within Within of this one
// (betterleaks writes it "5L" for five lines), unless Optional.
type Need struct {
	ID       string
	Within   string
	Optional bool
}

// Src is a rule's provenance. Lineage names the family (betterleaks, titus, own, ...), UpstreamID the
// id the rule has there, Commit the pinned commit it was read at, Licence the licence it was
// published under. Rewrite says how the regex differs from upstream's: "none" for as is, "split" for
// a change of text only (empty groups inside a key-like literal, a class written as ranges: the
// expression matches what it matched), and later T1, T2 or T3 for the rewrites of the plan.
type Src struct {
	Lineage    string
	UpstreamID string
	Commit     string
	Licence    string
	Rewrite    string
}

// Rule is one row of the table.
type Rule struct {
	ID         string
	Provider   string // the first word of the id, a heuristic that groups rules by service
	Desc       string
	Kind       Kind
	Keywords   []string // lower case; a window is looked at only where one occurs (none: every window)
	Re         string   // RE2; empty for a rule that only matches a path
	Group      int      // the capture group that is the secret; 0 is the first non-empty one, else the whole match
	Path       string   // RE2: the rule applies only to paths this matches; with no Re, the path is the finding
	Confidence string   // low, medium or high, as upstream labels it
	// Specificity is the effective one: betterleaks's 100 for a rule that sets none. A finding of a
	// rule with a higher value silences a finding of a lower one on the same line when its secret
	// contains the other's.
	Specificity int
	Filter      Filter
	// ComponentOnly rules fire only as a component of another (betterleaks's skipReport).
	ComponentOnly bool
	Needs         []Need
	Validates     bool // upstream has a live check for it; keyguard does not carry the recipe
	Src           Src
}
